  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for a retail customer.
   * The customer must provide the target company, a share count greater than 0,
   * a payment amount greater than 0, and a non-null allowance document.
   * The customer must be currently eligible to apply and must not already have an approved
   * application for the same company name.
   * Algorithm:
   * 1. Check that company is not null.
   * 2. Check that shares > 0.
   * 3. Check that amount > 0.
   * 4. Check that doc is not null.
   * 5. Check isEligibleForIPO().
   * 6. Check that there is no existing APPROVAL application in applications for company.name.
   * 7. If any validation fails, return false.
   * 8. Create a new Application with status PENDING, assigned company, customer, share, amountOfMoney, and allowance.
   * 9. Add the application to applications.
   * 10. Return true.
   * Related Features:
   * - canApplyForIPO
   * - applications
   * - isEligibleForIPO()
   * - createApplication(company, shares, amount, doc)
   * Related Classes: Company, Document, Application, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   *   - Must be non-null.
   * - shares : int
   *   - Number of shares requested.
   *   - Must be greater than 0.
   * - amount : double
   *   - Payment amount provided by the customer.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Allowance documentation.
   *   - Must be non-null.
   * Output:
   * - boolean
   * - true if the application record is created successfully.
   * - false otherwise.
   * Pre-condition:
   * - Customer exists and represents a retail customer.
   * - company is provided.
   * - shares > 0 and amount > 0.
   * - doc is not null.
   * - The customer is eligible for IPO.
   * - The customer has no approved application for the same company name.
   * Post-condition:
   * - If true, a new pending application is added to applications.
   * - The new application references this customer, the target company, the document, shares, and amount.
   * - If false, no new application is added.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0.0 || doc == null || !isEligibleForIPO())
    {
      return false;
    }

    if (applications != null)
    {
      for (Application application : applications)
      {
        if (application != null
            && application.getStatus() == ApplicationStatus.APPROVAL
            && application.getCompany() != null
            && company.getName() != null
            && company.getName().equals(application.getCompany().getName()))
        {
          return false;
        }
      }
    }

    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setStatus(ApplicationStatus.PENDING);
    application.setCompany(company);
    application.setCustomer(this);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    getApplications().add(application);
    return true;
    
  }

